design_text:
{
  "site_summary": "A west-facing partial shade balcony with moderate moisture, featuring filtered afternoon light and a cat and dog in the household.",
  "layout_strategy": "The scheme is structured into three distinct height layers: trailing plants cascade from the railing at eye level, lush upright perennials sit in containers at mid-height against the back wall, and a low, accessible pet grazing tray sits directly on the balcony floor.",
  "combination_logic": "The plants are combined to create a strong textural contrast between the fine, wispy foliage of ornamental grasses and the broad, glossy leaves of hostas and ferns. Soft pastel flowers emerge in spring, transitioning to rich foliage tones and seed heads in autumn. Each plant plays a specific role in contrasting heights and leaf shapes to maintain visual interest throughout the year.",
  "zones": [
    {
      "zone_name": "Railing Cascade",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On the outer balcony railing, receiving 4 hours of filtered western afternoon sun and gentle breezes.",
      "plants": [
        {
          "scientific_name": "Nepeta cataria",
          "common_name": "Catnip",
          "why": "Completely pet-safe and drapes softly over the edge of the hanging basket.",
          "role_in_combination": "Provides soft grey-green foliage colour and a delightful scent that interacts with the breeze, contrasting with darker green neighbours."
        },
        {
          "scientific_name": "Campanula poscharskyana",
          "common_name": "Trailing Bellflower",
          "why": "Thrives in partial shade and produces a cascade of star-shaped blue flowers.",
          "role_in_combination": "Adds a vibrant splash of seasonal blue colour and a delicate flower shape that spills down over the railing."
        }
      ],
      "maintenance": [
        "Water thoroughly when the top two inches of soil feel dry",
        "Feed with a balanced liquid fertiliser every two weeks in spring and summer",
        "Prune back long stems after flowering to encourage dense new growth"
      ]
    },
    {
      "zone_name": "Mid-Level Sanctuary",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "Against the back wall of the balcony in larger pots, sheltered from harsh winds and receiving dappled afternoon light.",
      "plants": [
        {
          "scientific_name": "Hosta sieboldiana",
          "common_name": "Plantain Lily",
          "why": "Loves partial shade and provides stunning architectural foliage without harming curious pets.",
          "role_in_combination": "Offers massive, ribbed blue-green leaves that create a bold textural contrast against fine grasses and trailing plants."
        },
        {
          "scientific_name": "Athyrium niponicum",
          "common_name": "Japanese Painted Fern",
          "why": "Brings metallic frond coloration and thrives in the exact partial shade conditions of this balcony.",
          "role_in_combination": "Contributes delicate, silvery-purple fronds that soften the heavy bulk of the hosta leaves."
        }
      ],
      "maintenance": [
        "Keep the potting mix evenly moist, ensuring good drainage to prevent rot",
        "Apply a slow-release granular fertiliser in early spring",
        "Cut back dead fronds and foliage to the base in late autumn"
      ]
    },
    {
      "zone_name": "Pet Grazing Corner",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "Directly on the floor in a quiet corner of the balcony, easily reached by both the indoor cat and the dog.",
      "plants": [
        {
          "scientific_name": "Dactylis glomerata",
          "common_name": "Pet Grass",
          "why": "Fast-germinating, highly appealing to cats and dogs for nibbling, and completely non-toxic.",
          "role_in_combination": "Provides an upright, vertical blade texture at ground level that contrasts with the rounded pots and sprawling upper layers."
        }
      ],
      "maintenance": [
        "Water lightly every few days to keep the shallow soil fresh",
        "Trim the grass back when it gets too leggy to encourage sweet fresh shoots",
        "Sow new grass seed every 4 to 6 weeks to maintain a lush grazing patch"
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers",
      "frequency": "Twice a week in summer, weekly in spring and autumn",
      "season": "Summer, Spring, Autumn"
    },
    {
      "task": "Apply organic liquid feed to mid-level and hanging containers",
      "frequency": "Every two weeks",
      "season": "Spring and Summer"
    },
    {
      "task": "Inspect foliage for pests like aphids and clear away fallen dead leaves",
      "frequency": "Monthly",
      "season": "All Seasons"
    }
  ],
  "care_cautions": [
    "Overwatering the hanging basket containers can lead to root rot, especially given the moderate moisture and filtered light conditions which slow down evaporation.",
    "The catnip in the railing cascade may attract neighbourhood cats if left unchecked, and heavy rubbing might damage the trailing stems.",
    "The ground-level pet grass tray can dry out very quickly in shallow soil and will need frequent resowing if heavily grazed by the dog."
  ],
  "pet_safety_note": "All selected plants (Catnip, Bellflower, Hosta, Japanese Painted Fern, and Pet Grass) are 100 percent non-toxic to cats and dogs, ensuring the household pets can safely explore and nibble."
}
